'use strict';
(() => {
 const C = window.TECHPATH;
 const KEY = 'techpath.learning.v1';
 const $ = (s) => document.querySelector(s);
 const escape = (v) => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const icons = {
 home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 lessons:'<path d="M12 5C8 2 3 4 3 4v15s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1v15"/>',
 session:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 roadmap:'<path d="M6 3v18m0-14h10a3 3 0 0 1 0 6H9a3 3 0 0 0 0 6h9"/><circle cx="6" cy="4" r="2"/><path d="m16 17 2 2-2 2"/>',
 notebook:'<rect x="5" y="3" width="15" height="18" rx="2"/><path d="M3 7h4M3 12h4M3 17h4M10 8h6M10 12h6"/>',
 glossary:'<path d="M4 4h16v16H4zM8 15l3-7 3 7m-5-2h4M16 9v6"/>',settings:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/>'
 };
 const svg = name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true">${icons[name]||icons.lessons}</svg>`;
 const today = ()=>new Date().toLocaleDateString('en-CA');
 const dateLabel = d=>new Date(d).toLocaleDateString('vi-VN',{day:'numeric',month:'short',year:'numeric'});
 const uid = ()=>globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
 const emptyState = ()=>({version:1,selected:'sql-proc',duration:60,drafts:{},attempts:[],sessions:[],notes:[],session:null,lastBackup:null,updatedAt:new Date().toISOString()});
 const validIds = new Set(C.lessons.map(l=>l.id));
 function validate(raw) {
  if(!raw || raw.version!==1 || !Array.isArray(raw.attempts)||!Array.isArray(raw.sessions)||!Array.isArray(raw.notes)||!raw.drafts||typeof raw.drafts!=='object'||Array.isArray(raw.drafts)) throw new Error('File không đúng định dạng TechPath v1.');
  const s=emptyState();
  if(raw.attempts.length>10000||raw.sessions.length>10000||raw.notes.length>10000)throw new Error('File có quá nhiều bản ghi.');
  const str=(x,max=200000)=>typeof x==='string'?x.slice(0,max):'';
  s.selected=validIds.has(raw.selected)?raw.selected:'sql-proc';
  s.duration=Number.isInteger(raw.duration)&&raw.duration>=15&&raw.duration<=240?raw.duration:60;
  for(const [k,v] of Object.entries(raw.drafts))if(validIds.has(k)&&v&&typeof v==='object')s.drafts[k]={code:str(v.code),output:str(v.output),notes:str(v.notes),question:str(v.question),hints:Math.min(3,Math.max(0,Number(v.hints)||0)),solution:!!v.solution,mode:v.mode==='transfer'?'transfer':'standard',checks:Array.isArray(v.checks)?v.checks.map(Boolean).slice(0,10):[]};
  s.attempts=raw.attempts.filter(a=>a&&validIds.has(a.lessonId)&&!isNaN(Date.parse(a.at))).map(a=>({id:str(a.id,80)||uid(),lessonId:a.lessonId,at:a.at,code:str(a.code),output:str(a.output),notes:str(a.notes),question:str(a.question),hints:Math.min(3,Math.max(0,Number(a.hints)||0)),solution:!!a.solution,mode:a.mode==='transfer'?'transfer':'standard',assessment:['independent','assisted','retry'].includes(a.assessment)?a.assessment:'retry',checks:Array.isArray(a.checks)?a.checks.map(Boolean).slice(0,10):[]}));
  s.sessions=raw.sessions.filter(x=>x&&!isNaN(Date.parse(x.at))).map(x=>({id:str(x.id,80)||uid(),at:x.at,lessonId:validIds.has(x.lessonId)?x.lessonId:'sql-proc',planned:Math.min(240,Math.max(15,Number(x.planned)||60)),minutes:Math.min(1440,Math.max(0,Number(x.minutes)||0)),reflection:str(x.reflection,10000)}));
  s.notes=raw.notes.filter(x=>x&&typeof x.text==='string'&&!isNaN(Date.parse(x.at))).map(x=>({id:str(x.id,80)||uid(),at:x.at,text:str(x.text,50000)}));
  s.lastBackup=!isNaN(Date.parse(raw.lastBackup))?raw.lastBackup:null;
  if(raw.session&&validIds.has(raw.session.lessonId)&&Number.isFinite(raw.session.elapsed)&&raw.session.elapsed>=0&&Number.isFinite(raw.session.duration)&&raw.session.duration>=15&&raw.session.duration<=240){s.session={id:str(raw.session.id,80)||uid(),lessonId:raw.session.lessonId,duration:raw.session.duration,elapsed:raw.session.elapsed,running:!!raw.session.running,started:Date.now()}; if(raw.session.running&&Number.isFinite(raw.session.started))s.session.elapsed+=Math.max(0,Date.now()-raw.session.started);}
  return s;
 }
 let state=emptyState(), storageError=false;
 try{const saved=localStorage.getItem(KEY);if(saved)state=validate(JSON.parse(saved));}catch(e){storageError=true;}
 let lessonTab='learn',moduleFilter='all',lessonSearch='',notebookSearch='',vocabSearch='',reviewPacket='',saveTimer,renderedLessonId=null;
 function save(){state.updatedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='Đã lưu trên thiết bị này';storageError=false;}catch{$('#save-status').textContent='Chưa lưu được — hãy xuất sao lưu';storageError=true;}}
 function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
 function download(name,text,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 async function copy(t){try{await navigator.clipboard.writeText(t);toast('Đã copy.');}catch{showModal('Copy nội dung',`<p>Trình duyệt chưa cho phép clipboard. Chọn nội dung bên dưới và copy thủ công.</p><textarea readonly>${escape(t)}</textarea>`);}}
 function showModal(title,html){$('#modal-body').innerHTML=`<h2>${escape(title)}</h2>${html}`;$('#modal').showModal();}
 const codeBlock = code=>`<div class="code-wrap"><button type="button" class="button secondary" data-copy-code>Copy</button><pre><code>${escape(code)}</code></pre></div>`;
 const moduleOf = l=>C.modules.find(m=>m.id===l.module);
 const lesson = id=>C.lessons.find(l=>l.id===id)||C.lessons[5];
 const attemptsFor=id=>state.attempts.filter(a=>a.lessonId===id);
 function status(id){const a=attemptsFor(id),ind=a.filter(x=>x.assessment==='independent');const dates=new Set(ind.map(x=>new Date(x.at).toLocaleDateString('en-CA')));if(dates.size>=2&&ind.some(x=>x.mode==='transfer'))return 'solid';if(ind.length)return 'independent';if(a.length)return 'practice';return 'new';}
 const statusText=s=>({solid:'Tự làm + chuyển giao',independent:'Đã tự làm',practice:'Đang luyện',new:'Chưa tự đánh giá'}[s]);
 function draft(id){if(!state.drafts[id])state.drafts[id]={code:'',output:'',notes:'',question:'',hints:0,solution:false,mode:'standard',checks:[]};return state.drafts[id];}
 function dueLessons(){return C.lessons.filter(l=>{const a=attemptsFor(l.id);if(!a.length)return false;const last=a[a.length-1];const n=a.filter(x=>x.assessment==='independent').length;const days=last.assessment==='independent'?[1,3,7,14][Math.min(Math.max(n-1,0),3)]:1;return Date.now()-Date.parse(last.at)>=days*86400000;});}
 function head(k,title,sub,extra=''){return `<div class="page-head"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`;}
 const linkLesson = (l,text='Mở bài →')=>`<a class="text-link" href="#lesson/${l.id}">${escape(text)}</a>`;
 function home(){
  const l=lesson(state.selected), independent=C.lessons.filter(x=>['independent','solid'].includes(status(x.id))).length,minutes=state.sessions.reduce((n,s)=>n+s.minutes,0),due=dueLessons();
  return head('YOUR SPACE, YOUR PACE','Học có hướng. Tiến bộ từng bước.','Một buổi tập trung, một vấn đề hiểu rõ hơn. Hôm nay mình tiếp tục từ nơi đã dừng.',`<span class="date-tag">${new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long'})}</span>`)+`
  <div class="grid-home"><div><section class="card hero"><span class="eyebrow">TIẾP TỤC HÀNH TRÌNH <span style="opacity:.4"> / </span> ${escape(moduleOf(l).name.toUpperCase())}</span><h2>${escape(l.title)}</h2><p>${escape(l.summary)}</p><div class="hero-bottom"><a class="button" href="#lesson/${l.id}">Tiếp tục học <span>↗</span></a><span class="meta">${l.minutes} phút gợi ý · Thực hành trong SSMS${l.module==='sql'?'':' / công cụ tương ứng'}</span></div></section>
  <div class="stats"><div class="stat"><span>TỰ LÀM ĐƯỢC</span><strong>${independent}<small>/ ${C.lessons.length} bài</small></strong><span class="hint">Bạn tự xác nhận sau thực hành</span></div><div class="stat"><span>THỜI GIAN TẬP TRUNG</span><strong>${Math.floor(minutes/60)}<small>giờ ${minutes%60} phút</small></strong><span class="hint">Từ các buổi đã kết thúc</span></div><div class="stat"><span>CẦN ÔN LẠI</span><strong>${due.length}<small>bài</small></strong><span class="hint">Tự làm lại trước khi xem gợi ý</span></div></div>
  <section class="card"><div class="card-title"><h2>Kỹ năng đang xây dựng</h2><a class="text-link" href="#roadmap">Toàn bộ lộ trình ↗</a></div><div class="skill-list">${C.modules.slice(0,3).map(m=>{const ls=C.lessons.filter(l=>l.module===m.id),done=ls.filter(l=>['independent','solid'].includes(status(l.id))).length;return `<a class="skill-row" href="#lessons/${m.id}"><span class="skill-icon">${m.icon}</span><div class="skill-body"><strong>${m.name}</strong><small>${escape(m.goal)}</small><div class="progress"><span style="width:${done/ls.length*100}%"></span></div></div><span class="meta">${done}/${ls.length} ↗</span></a>`;}).join('')}</div></section>
  <div class="section-title"><h2>Ôn để tự làm được</h2><a class="text-link" href="#lessons">Thư viện bài học →</a></div><div class="card">${due.length?due.slice(0,3).map(l=>`<div class="mini-task"><span class="bullet">↺</span><div style="flex:1"><strong>${escape(l.title)}</strong><small>Làm lại mà không mở ghi chú, rồi tự đánh giá.</small></div>${linkLesson(l)}</div>`).join(''):`<p style="margin:0">Chưa có bài đến lịch ôn. Sau lần tự đánh giá đầu tiên, bài sẽ quay lại sau 1 ngày; những lần độc lập tiếp theo giãn thành 3, 7 rồi 14 ngày.</p>`}</div></div>
  <aside class="right-rail"><section class="card planner"><div class="eyebrow">THIẾT KẾ BUỔI HỌC</div><h2 style="margin-top:12px">Hôm nay bạn có bao lâu?</h2><p>Kế hoạch vừa với quỹ thời gian của bạn.</p><div class="time-options">${[30,60,90,120].map(t=>`<button class="time-choice ${state.duration===t?'selected':''}" data-duration="${t}">${t}<small>PHÚT</small></button>`).join('')}</div><div class="inline-input"><input id="custom-duration" aria-label="Số phút tùy chọn" type="number" min="15" max="240" value="${state.duration}"><span class="subtle">phút · 15–240</span></div><button class="button full" style="margin-top:17px" data-start-session>${state.session?'Mở buổi đang học':'Tạo buổi học'} <span>→</span></button><p class="planner-note">Ôn nhanh · Thực hành · Tự kiểm tra</p></section>
  <section class="card"><div class="card-title"><h3>Cách học của bạn</h3><span class="pill green">CÁ NHÂN</span></div><div class="mini-task"><span class="bullet">1</span><div><strong>Tự suy luận trước</strong><small>Chỉ mở một gợi ý khi thật sự bí.</small></div></div><div class="mini-task"><span class="bullet">2</span><div><strong>Làm trong công cụ thật</strong><small>SSMS, Windows và dữ liệu thực hành.</small></div></div><div class="mini-task"><span class="bullet">3</span><div><strong>Giải thích lại cách làm</strong><small>Chuẩn bị cho tình huống và phỏng vấn.</small></div></div></section><section class="card" style="background:#1b2420"><p class="quote">“Query chạy được là bước đầu. Hiểu vì sao nó đúng mới là thứ mình giữ lại.”</p><div class="quote-label">GHI NHỚ CHO HÔM NAY</div></section></aside></div>`;
 }
 function lessonsView(filter){if(filter)moduleFilter=filter;const filtered=C.lessons.filter(l=>(moduleFilter==='all'||l.module===moduleFilter)&&(l.title+' '+l.summary).toLowerCase().includes(lessonSearch.toLowerCase()));return head('CURRICULUM','Thư viện bài học','Mỗi bài có đề thực hành, gợi ý từng nấc, bài chuyển giao và checklist tự kiểm tra.')+`<input class="search" id="lesson-search" type="search" aria-label="Tìm bài học" placeholder="Tìm theo chủ đề, kỹ năng…" value="${escape(lessonSearch)}"><div class="tabs">${[{id:'all',name:'Tất cả'},...C.modules].map(m=>`<button class="tab ${moduleFilter===m.id?'active':''}" data-filter="${m.id}">${m.name}</button>`).join('')}</div><div class="lesson-grid">${filtered.map(l=>`<a class="card lesson-card" href="#lesson/${l.id}"><div class="lesson-index"><span>${escape(moduleOf(l).icon)} / ${String(C.lessons.indexOf(l)+1).padStart(2,'0')}</span><span class="pill ${['solid','independent'].includes(status(l.id))?'green':''}">${statusText(status(l.id))}</span></div><h3>${escape(l.title)}</h3><p>${escape(l.summary)}</p><div class="meta"><span>${l.minutes} phút${l.prior?' · Đã thực hành trong chat':''}</span><span>↗</span></div></a>`).join('')||'<p>Không có bài khớp từ khóa.</p>'}</div>`;}
 function lessonView(id){const l=lesson(id),d=draft(l.id);state.selected=l.id;save();return `<a class="back" href="#lessons">← Thư viện bài học</a>`+head(escape(moduleOf(l).name.toUpperCase()),escape(l.title),escape(l.summary))+`<div class="lesson-layout"><article><div class="lesson-title-row"><span class="pill">${l.minutes} phút gợi ý</span><span class="pill green">${statusText(status(l.id))}</span>${l.prior?'<span class="pill">Đã thực hành trong chat · Chưa xác nhận độc lập</span>':''}</div><div class="task-tabs"><button data-lesson-tab="learn" class="${lessonTab==='learn'?'active':''}">01 · Hiểu bài</button><button data-lesson-tab="practice" class="${lessonTab==='practice'?'active':''}">02 · Thực hành</button><button data-lesson-tab="reflect" class="${lessonTab==='reflect'?'active':''}">03 · Tự kiểm tra</button></div>
  ${lessonTab==='learn'?`<div class="card lesson-body">${l.body}<h3>Việc bạn cần giải quyết</h3><div class="callout">${escape(l.task)}</div>${l.resources.length?`<h3>Tài liệu đọc thêm</h3>${l.resources.map(r=>`<a class="resource" href="${r[1]}" target="_blank" rel="noopener">${escape(r[0])} ↗</a>`).join('')}`:''}<button class="button" data-lesson-tab="practice">Bắt đầu thực hành →</button></div>`:lessonTab==='practice'?practice(l,d):reflect(l,d)}
  </article><aside class="sticky"><section class="card hint-card"><div class="eyebrow">MỘT BƯỚC NHỎ KHI BÍ</div><h3 style="margin-top:13px">Bạn vẫn là người giải bài.</h3><p>Đây là gợi ý soạn sẵn theo bài. Muốn hỏi đúng đoạn code đang bí, dùng “Nhờ review”.</p>${l.hints.slice(0,d.hints).map((h,i)=>`<div class="hint"><div class="hint-number">GỢI Ý ${i+1} / ${l.hints.length}</div>${escape(h)}</div>`).join('')}<button class="button secondary full" data-hint ${d.hints>=l.hints.length?'disabled':''}>${d.hints===0?'Cho mình một gợi ý':d.hints<l.hints.length?'Gợi ý thêm một chút':'Đã mở hết gợi ý'}</button><p class="save-meta">${d.hints?`Lần thử này đã dùng ${d.hints} gợi ý.`:'Chưa dùng gợi ý trong lần thử này.'}</p></section><section class="card"><h3>Bài chuyển giao</h3><p>${escape(l.transfer)}</p><button class="text-link" data-transfer>${d.mode==='transfer'?'Đang làm bài chuyển giao ✓':'Chuyển sang yêu cầu này →'}</button></section><section class="card"><h3>Môi trường thực hành</h3><p>${l.module==='sql'?'SQL Server / SSMS · SupportLab. App không thực thi SQL và không tự đọc query chưa lưu trong SSMS.':'Dùng công cụ tương ứng trên máy. Lưu kết quả và cách kiểm tra vào phần thực hành.'}</p>${l.module==='sql'?'<button class="text-link" data-seed>↓ Dataset SupportLab (.sql)</button>':''}<a class="resource" href="#settings">Cấu hình review trong SSMS ↗</a></section></aside></div>`;}
 function practice(l,d){return `<section class="card"><div class="card-title"><h2>${d.mode==='transfer'?'Bài chuyển giao':'Bài thực hành'}</h2><span class="pill">${d.mode==='transfer'?'YÊU CẦU MỚI':'TỰ SUY LUẬN'}</span></div><p>${escape(d.mode==='transfer'?l.transfer:l.task)}</p><label for="draft-code">Code / phương án của bạn</label><textarea id="draft-code" class="code-input" spellcheck="false" placeholder="Viết trong SSMS, rồi dán hoặc nhập file .sql vào đây để lưu và chuẩn bị review…">${escape(d.code)}</textarea><div class="save-meta">Tự lưu trên thiết bị · Nội dung được giữ nguyên khi đổi bài</div><div class="actions"><button class="button secondary" data-import-sql>↑ Nhập file .sql</button><button class="button ghost" data-download-code>↓ Tải bài làm</button><button class="button ghost" data-new-attempt>Bắt đầu lần thử mới</button></div><label for="draft-output">Kết quả / thông báo lỗi (giữ nguyên văn khi có thể)</label><textarea id="draft-output" placeholder="Dán kết quả hoặc lỗi từ Messages trong SSMS…">${escape(d.output)}</textarea><label for="draft-notes">Mình đang suy luận thế nào?</label><textarea id="draft-notes" placeholder="Mục tiêu → dữ kiện → giả thuyết → bước kiểm tra tiếp theo…">${escape(d.notes)}</textarea><label for="draft-question">Chỗ mình muốn hỏi review</label><textarea id="draft-question" placeholder="Ví dụ: Vì sao order không có payment bị mất khỏi kết quả? Chỉ gợi ý chỗ cần xem lại, đừng sửa toàn bộ code.">${escape(d.question)}</textarea><div class="actions"><button class="button" data-review>Nhờ review · Chuẩn bị ngữ cảnh ↗</button><button class="button secondary" data-save-attempt>Lưu lần thử</button><button class="button ghost" data-lesson-tab="reflect">Tự kiểm tra →</button></div><p class="save-meta">Review tạo nội dung để copy vào Copilot Chat trong SSMS hoặc chat bạn đang dùng; app không gọi API AI.</p><hr class="divider"><details><summary>Xem kết quả kỳ vọng · đối chiếu sau khi tự chạy</summary><p style="margin-top:12px">${escape(l.expected)}</p></details><details id="solution"><summary>Lời giải tham khảo · bấm nút xác nhận để mở</summary><p>Xem lời giải sẽ ghi nhận lần thử hiện tại có trợ giúp.</p>${d.solution?codeBlock(l.solution):'<button class="button secondary" data-solution>Mở lời giải tham khảo</button>'}</details></section>`;}
 function reflect(l,d){const a=attemptsFor(l.id);return `<section class="card"><h2>Tự làm được đến đâu?</h2><p>Đây là tự đánh giá, không phải chấm SQL tự động. Chọn sau khi đã chạy và đối chiếu trong công cụ thực hành.</p><div class="callout">${escape(l.expected)}</div><div class="checklist">${l.checks.map((c,i)=>`<label><input type="checkbox" data-check="${i}" ${d.checks[i]?'checked':''}>${escape(c)}</label>`).join('')}</div><label for="draft-notes">Điều đã hiểu / lỗi muốn ghi nhớ</label><textarea id="draft-notes" placeholder="Viết lại bằng lời của bạn…">${escape(d.notes)}</textarea><div class="actions"><button class="button" data-assess="independent">Tự làm được</button><button class="button secondary" data-assess="assisted">Làm được nhờ gợi ý</button><button class="button ghost" data-assess="retry">Cần luyện lại</button></div><p class="save-meta">“Tự làm được” cần đủ checklist và không dùng gợi ý/lời giải trong lần thử này. Mức “Tự làm + chuyển giao” cần hai ngày thực hành độc lập, gồm ít nhất một bài chuyển giao.</p><hr class="divider"><h3>Lịch sử của bài</h3>${a.length?a.slice().reverse().slice(0,6).map(x=>`<div class="mini-task"><span class="bullet">${x.assessment==='independent'?'✓':'↺'}</span><div><strong>${x.assessment==='independent'?'Tự làm được':x.assessment==='assisted'?'Có trợ giúp':'Cần luyện lại'}</strong><small>${dateLabel(x.at)} · ${x.mode==='transfer'?'Chuyển giao':'Bài chính'} · ${x.hints} gợi ý</small></div></div>`).join(''):'<p>Chưa có lần tự đánh giá. Bài cũ trong chat được giữ làm bối cảnh, không tự tính là đã thành thạo.</p>'}</section>`;}
 function planBlocks(t,l){const recap=Math.max(3,Math.min(8,Math.floor(t*.10))),learn=Math.max(2,Math.min(15,Math.floor(t*.18))),reflect=Math.max(2,Math.min(15,Math.floor(t*.12))),log=Math.max(2,Math.min(5,Math.floor(t*.08))),pause=t>=90?5:0,practice=t-recap-learn-reflect-log-pause;let blocks=[{n:'Gọi lại kiến thức',m:recap,p:dueLessons()[0]?`Ôn: ${dueLessons()[0].title}. Viết lại logic trước khi mở ghi chú.`:'Đóng ghi chú. Nhắc lại ON/WHERE, grain và một lỗi từng mắc.'},{n:'Hiểu yêu cầu',m:learn,p:`Đọc “${l.title}”. Viết mục tiêu và kết quả mong đợi bằng lời của mình.`},{n:'Thực hành tập trung',m:practice,p:'Làm trong SSMS/công cụ tương ứng. Nếu bí, ghi chỗ bí và mở một gợi ý.'}];if(pause)blocks.push({n:'Nghỉ ngắn',m:pause,p:'Rời màn hình, sau đó quay lại giải thích bước đang làm.'});blocks.push({n:'Tự kiểm tra / chuyển giao',m:reflect,p:'Đối chiếu kết quả, kiểm tra tình huống biên. Nếu đủ thời gian, thử yêu cầu mới.'},{n:'Ghi nhận & hẹn ôn',m:log,p:'Lưu bài làm, ghi lỗi và tự đánh giá mức độc lập.'});return blocks;}
 function elapsed(){const s=state.session;return s?s.elapsed+(s.running?Math.max(0,Date.now()-s.started):0):0;}
 function sessionView(){const s=state.session;if(!s)return head('FOCUS SESSION','Một buổi học vừa sức.','Chọn thời gian ở Tổng quan để tạo kế hoạch. Lịch linh hoạt theo từng ngày.')+`<section class="card empty"><h3>Chưa có buổi đang học</h3><p>30 phút vẫn đủ để hiểu rõ một vấn đề.</p><a class="button" href="#home">Thiết kế buổi học →</a></section>`;const l=lesson(s.lessonId);let p=0;return head('FOCUS SESSION',`${s.duration} phút dành cho mình`,escape(l.title))+`<div class="lesson-layout"><section class="card"><div class="card-title"><h2>Kế hoạch của buổi này</h2><span class="pill green">${s.duration} PHÚT</span></div>${planBlocks(s.duration,l).map(b=>{const range=`${p}–${p+b.m}`;p+=b.m;return `<div class="plan-block"><span class="plan-time">${range}′</span><div><h3>${escape(b.n)}</h3><p>${escape(b.p)}</p></div></div>`;}).join('')}<div class="actions"><a class="button" href="#lesson/${l.id}">Vào bài học ↗</a></div></section><aside><section class="card"><div class="eyebrow">THỜI GIAN ĐÃ TẬP TRUNG</div><div class="timer" id="timer">${formatTime(elapsed())}</div><p id="timer-note">${s.running?'Đang đếm · Có thể đổi màn hình trong app.':'Đang tạm dừng. Bấm tiếp tục khi sẵn sàng.'}</p><div class="actions"><button class="button secondary" data-pause>${s.running?'Tạm dừng':'Tiếp tục'}</button><button class="button ghost" data-finish-session>Kết thúc buổi</button></div><p class="save-meta">Đồng hồ lưu thời gian thực, không tự đánh dấu bài đã hiểu. Để tránh tính thời gian nghỉ, tạm dừng trước khi đóng app.</p></section><section class="card"><h3>Ít hơn cũng được.</h3><p>Chưa hoàn thành bài thì giữ nguyên bản nháp. Buổi sau tiếp tục; không cần chạy theo số bài.</p></section></aside></div>`;}
 function formatTime(ms){const sec=Math.floor(ms/1000);return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
 function roadmap(){return head('YOUR DIRECTION','Từ tìm lỗi đến hiểu hệ thống.','Lộ trình phục vụ Application Support / Data Operations, với SQL làm thế mạnh. Các chặng mở để bạn tự điều chỉnh.')+C.modules.map((m,i)=>`<section class="card roadmap-module"><div class="eyebrow">CHẶNG ${String(i+1).padStart(2,'0')} / ${m.tag}</div><h2>${m.name}</h2><p>${m.desc}</p><div class="roadmap-items">${C.lessons.filter(l=>l.module===m.id).map(l=>`<a href="#lesson/${l.id}"><span>${escape(l.title)}</span><span class="meta">${status(l.id)==='new'?'↗':'✓'}</span></a>`).join('')}</div></section>`).join('')+`<section class="card"><h3>Sau nền tảng này</h3><p>Chọn sâu hơn dựa trên công việc thực tế: Python tự động hóa, Data Engineering hoặc phân tích dữ liệu. Tiếng Nhật học riêng; tiếng Anh kỹ thuật được lồng vào thuật ngữ và ticket.</p></section>`;}
 function notebook(){const term=notebookSearch.toLowerCase();const attempts=state.attempts.slice().reverse().filter(a=>(lesson(a.lessonId).title+a.code+a.notes+a.output).toLowerCase().includes(term));return head('LEARNING JOURNAL','Lưu lại cách mình đã nghĩ.','Code, lỗi và nhận xét theo từng lần thử. Nội dung của bạn được lưu trên trình duyệt này.',`<button class="button secondary" data-export-md>↓ Xuất Markdown</button>`)+`<input type="search" class="search" id="notebook-search" placeholder="Tìm trong code, ghi chú và bài học…" aria-label="Tìm nhật ký" value="${escape(notebookSearch)}"><section class="card"><h3>Ghi chú nhanh</h3><label for="quick-note">Một phát hiện, một lỗi hay câu hỏi muốn giữ lại</label><textarea id="quick-note" placeholder="Hôm nay mình hiểu vì sao…"></textarea><button class="button secondary" style="margin-top:10px" data-add-note>Lưu ghi chú</button></section><div class="section-title"><h2>Các lần thực hành (${attempts.length})</h2><button class="text-link" data-export-md>Xuất tất cả ↗</button></div>${attempts.length?attempts.slice(0,50).map(a=>`<article class="card notebook-item"><div class="tagline"><span class="pill ${a.assessment==='independent'?'green':''}">${a.assessment==='independent'?'Độc lập':a.assessment==='assisted'?'Có trợ giúp':'Chưa tự đánh giá / cần luyện'}</span><span class="meta">${dateLabel(a.at)}</span></div><h3>${escape(lesson(a.lessonId).title)}</h3>${a.notes?`<p style="white-space:pre-wrap">${escape(a.notes)}</p>`:''}${a.code?`<details><summary>Xem bài làm đã lưu</summary>${codeBlock(a.code)}</details>`:''}${a.output?`<details><summary>Kết quả / lỗi</summary><pre class="code">${escape(a.output)}</pre></details>`:''}${linkLesson(lesson(a.lessonId),'Quay lại bài →')}</article>`).join(''):'<section class="card empty"><h3>Nhật ký bắt đầu từ một lần thử.</h3><p>Ở bài học, bấm “Lưu lần thử” hoặc tự đánh giá để lưu mốc thực hành.</p></section>'}<div class="section-title"><h2>Ghi chú cá nhân</h2></div>${state.notes.slice().reverse().filter(n=>n.text.toLowerCase().includes(term)).map(n=>`<article class="card notebook-item"><span class="meta">${dateLabel(n.at)}</span><p style="white-space:pre-wrap;margin-top:10px">${escape(n.text)}</p></article>`).join('')||'<p class="subtle">Chưa có ghi chú.</p>'}${state.sessions.length?'<div class="section-title"><h2>Buổi đã học</h2></div>'+state.sessions.slice().reverse().slice(0,10).map(s=>`<section class="card notebook-item"><span class="meta">${dateLabel(s.at)} · ${s.minutes} phút thực tế / ${s.planned} phút kế hoạch</span><h3 style="margin-top:9px">${escape(lesson(s.lessonId).title)}</h3><p style="white-space:pre-wrap">${escape(s.reflection)}</p></section>`).join(''):''}`;}
 function glossary(){return head('TECHNICAL ENGLISH','Hiểu thuật ngữ. Dùng đúng ngữ cảnh.','Giải thích tiếng Việt và thuật ngữ tiếng Anh đi cùng các bài thực hành.')+`<input class="search" id="vocab-search" type="search" aria-label="Tìm thuật ngữ" value="${escape(vocabSearch)}" placeholder="Tìm CTE, root cause, Power Query…"><div class="vocab-grid">${C.glossary.filter(t=>t.join(' ').toLowerCase().includes(vocabSearch.toLowerCase())).map(([t,d,m])=>`<article class="card"><span class="pill">${m}</span><h3 style="margin-top:13px;margin-bottom:4px">${escape(t)}</h3><p>${escape(d)}</p></article>`).join('')}</div>`;}
 const tutorPrompt=`Bạn là gia sư kỹ thuật của tôi. Tôi học SQL để làm Application Support / Data Operations.
Chỉ phản hồi khi tôi hỏi. Ưu tiên để tôi tự suy luận.
Mỗi lần chỉ chỉ ra MỘT điểm đang cản trở, giải thích ngắn bằng tiếng Việt kèm thuật ngữ tiếng Anh.
Hỏi một câu gợi mở hoặc đưa một gợi ý nhỏ; dừng để tôi thử.
Không tự viết lại toàn bộ query, không tiết lộ lời giải trừ khi tôi yêu cầu rõ.
Khi tôi hỏi về tối ưu, yêu cầu execution plan / index / dữ liệu đo nếu chưa đủ bằng chứng.
Không tự thực thi hoặc sửa dữ liệu, schema hay quyền truy cập.
Trong SSMS Chat, hãy dùng ngữ cảnh query đang mở; nếu thiếu thì hỏi lại.`;
 function settings(){return head('WORKSPACE SETTINGS','Giữ cách học theo ý mình.','Không cần API key. Lưu cục bộ, xuất/nhập giữa PC và laptop; source code tách riêng với tiến độ cá nhân.')+`<div class="settings-grid"><section class="card"><h2>Dữ liệu & hai thiết bị</h2><p>Tiến độ nằm trong localStorage của trình duyệt và địa chỉ app hiện tại. PC và laptop không tự đồng bộ. Xuất file sau buổi học, rồi nhập ở máy còn lại.</p><div class="actions"><button class="button" data-backup>↓ Xuất sao lưu JSON</button><button class="button secondary" data-import>↑ Nhập sao lưu</button></div><p class="save-meta">${state.lastBackup?'Lần xuất gần nhất: '+dateLabel(state.lastBackup):'Chưa xuất bản sao lưu.'}</p><p class="notice">Nhập sao lưu sẽ thay thế tiến độ trên thiết bị này. App yêu cầu bạn tải bản hiện tại trước khi xác nhận. Nên giữ JSON cá nhân ngoài repository công khai.</p><button class="text-link" data-export-md>↓ Xuất nhật ký Markdown</button><hr class="divider"><h3>Dataset thực hành</h3><p>Dataset giả lập giống SupportLab đã học. Nếu đã có các bảng, script dừng và không ghi đè dữ liệu.</p><button class="button secondary" data-seed>↓ Tải SupportLab.sql</button></section>
 <section class="card"><h2>Review đúng lúc trong SSMS</h2><p>GitHub Copilot Chat hỗ trợ ngữ cảnh query đang mở trên SSMS 22+. Copilot Free có giới hạn sử dụng. Kiểm tra SSMS bằng Help → About; phiên bản SQL Server 2022 không phải phiên bản SSMS.</p><ol class="lesson-body"><li>Cài/bật AI Assistance bằng Visual Studio Installer nếu chưa có.</li><li>Đăng nhập GitHub và chọn Copilot Free; không cần nhập API key vào app này.</li><li>Đặt Inline Suggestions / Invocation thành Manual, hoặc tắt completions để không bị gợi ý khi đang suy nghĩ.</li><li>Dùng Chat để hỏi review khi cần. Agent mode có thể thiếu ngữ cảnh editor; bài học này ưu tiên Chat.</li><li>Copy nguyên tắc gia sư bên dưới, rồi thêm yêu cầu từ nút “Nhờ review” trong bài.</li></ol><button class="button secondary" data-tutor>Copy nguyên tắc gia sư</button><a class="resource" target="_blank" rel="noopener" href="https://learn.microsoft.com/en-us/ssms/github-copilot/get-started">Microsoft · Bắt đầu với Copilot trong SSMS ↗</a><a class="resource" target="_blank" rel="noopener" href="https://learn.microsoft.com/en-us/ssms/github-copilot/code-completions">Microsoft · Cấu hình gợi ý thủ công ↗</a><a class="resource" target="_blank" rel="noopener" href="https://docs.github.com/en/copilot/get-started/plans">GitHub · Giới hạn gói Free ↗</a><p class="subtle">App không đọc trực tiếp SSMS, không gửi code đi tự động và không chấm bằng AI. Các gợi ý trong bài là nội dung biên soạn.</p></section>
 <section class="card"><h2>Tiêu chí tiến bộ</h2><p>“Tự làm được” là tự đánh giá sau khi chạy đúng, đủ checklist, không mở gợi ý/lời giải trong lần thử. “Tự làm + chuyển giao” cần hai ngày độc lập và ít nhất một bài yêu cầu mới. Đây không phải chứng nhận hay điểm từ hệ thống chấm tự động.</p><p>Buổi ôn dùng khoảng cách 1, 3, 7, 14 ngày sau các lần độc lập; lần cần trợ giúp quay lại sau 1 ngày.</p></section><section class="card"><h2>Chi phí & source</h2><p>Bản app này không dùng API trả phí hay backend bắt buộc. Có thể chạy source cục bộ hoặc host tĩnh. Dịch vụ AI bên ngoài có giới hạn gói riêng.</p><p>GitHub lưu source code; JSON sao lưu chứa tiến độ cá nhân. Việc push source không tự mang tiến độ sang thiết bị khác.</p><p class="subtle">TechPath v0.1 · ${C.lessons.length} bài · ${C.glossary.length} thuật ngữ</p></section></div>`;}
 function render(){const hash=location.hash.slice(1)||'home';const [page,id]=hash.split('/');let html;const map={home:'Tổng quan',lessons:'Bài học',session:'Buổi học',roadmap:'Lộ trình',notebook:'Nhật ký',glossary:'Thuật ngữ',settings:'Cài đặt'};const active=page==='lesson'?'lessons':page;$('#nav').innerHTML=Object.entries(map).filter(([k])=>k!=='settings').map(([k,v])=>`<a href="#${k}" class="${active===k?'active':''}" ${active===k?'aria-current="page"':''}>${svg(k)}<span>${v}</span></a>`).join('');$('#breadcrumb').textContent=`Workspace / ${map[active]||'Tổng quan'}`;if(page==='lesson')html=lessonView(id);else if(page==='lessons')html=lessonsView(id);else if(page==='session')html=sessionView();else if(page==='roadmap')html=roadmap();else if(page==='notebook')html=notebook();else if(page==='glossary')html=glossary();else if(page==='settings')html=settings();else html=home();$('#main').innerHTML=html;renderedLessonId=page==='lesson'?lesson(id).id:null;document.title=`${page==='lesson'?lesson(id).title:map[page]||'Tổng quan'} · TechPath`;if(storageError)$('#save-status').textContent='Không đọc/lưu được dữ liệu — hãy sao lưu';}
 function currentLesson(){return lesson(location.hash.split('/')[1]||state.selected);}
 function syncDraft(){if(!renderedLessonId)return;const d=draft(renderedLessonId);for(const k of ['code','output','notes','question']){const el=$('#draft-'+k);if(el)d[k]=el.value;}}
 function storeAttempt(assessment='retry'){syncDraft();const l=currentLesson(),d=draft(l.id);state.attempts.push({id:uid(),lessonId:l.id,at:new Date().toISOString(),...structuredClone(d),assessment});save();}
 function packet(){syncDraft();const l=currentLesson(),d=draft(l.id);return `${tutorPrompt}\n\nBài: ${l.title}\nYêu cầu: ${d.mode==='transfer'?l.transfer:l.task}\nMôi trường: ${l.module==='sql'?'SQL Server 2022 Express / SSMS / database SupportLab':'Windows / công cụ của bài'}\nSchema SQL khi liên quan:\nCustomers(customer_id PK, customer_name, email NULL)\nOrders(order_id PK, customer_id, order_date, order_status, order_total decimal(12,2))\nPayments(payment_id PK, order_id, payment_date NULL, payment_status, payment_amount decimal(12,2))\nMột order có thể có nhiều payment. Chỉ Succeeded được tính thành công.\n\nBài làm:\n${d.code||'(Hãy xem query đang mở trong SSMS; tôi chưa dán code vào app.)'}\n\nKết quả / lỗi:\n${d.output||'(chưa cung cấp)'}\n\nSuy luận của tôi:\n${d.notes||'(chưa ghi)'}\n\nTôi muốn hỏi:\n${d.question||'Hãy review logic và chỉ gợi ý nhỏ ở điểm tôi cần tự kiểm tra tiếp.'}`;}
 function backup(){syncDraft();state.lastBackup=new Date().toISOString();save();download(`techpath-backup-${today()}.json`,JSON.stringify(state,null,2),'application/json');toast('Đã xuất tiến độ. Giữ file để nhập trên máy khác.');}
 function exportMd(){syncDraft();const md=['# TechPath — Learning journal',`Exported: ${new Date().toISOString()}`,'',...state.attempts.map(a=>`## ${lesson(a.lessonId).title}\n\n${a.at} · ${a.assessment} · ${a.mode}\n\n### Bài làm\n\n\`\`\`sql\n${a.code.replace(/```/g,'` ` `')}\n\`\`\`\n\n### Kết quả\n\n${a.output}\n\n### Ghi chú\n\n${a.notes}\n`),'## Ghi chú riêng','',...state.notes.map(n=>`${n.at}\n\n${n.text}\n`),'## Buổi học','',...state.sessions.map(s=>`${s.at} · ${s.minutes} phút\n\n${s.reflection}\n`)];download(`techpath-journal-${today()}.md`,md.join('\n'));}
 document.addEventListener('input',e=>{const el=e.target;if(el.id.startsWith('draft-')){syncDraft();clearTimeout(saveTimer);saveTimer=setTimeout(save,300);}if(el.id==='custom-duration'){const n=Number(el.value);if(Number.isInteger(n)&&n>=15&&n<=240){state.duration=n;save();document.querySelectorAll('[data-duration]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.duration)===n));}}for(const [id,set] of [['lesson-search',v=>lessonSearch=v],['notebook-search',v=>notebookSearch=v],['vocab-search',v=>vocabSearch=v]])if(el.id===id){const pos=el.selectionStart;set(el.value);render();const n=$('#'+id);n.focus();n.setSelectionRange(pos,pos);}});
 document.addEventListener('keydown',e=>{if(e.target.id==='draft-code'&&e.key==='Tab'){e.preventDefault();const el=e.target,start=el.selectionStart,end=el.selectionEnd;el.setRangeText('    ',start,end,'end');syncDraft();save();}});
 document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){draft(currentLesson().id).checks[Number(e.target.dataset.check)]=e.target.checked;syncDraft();save();}});
 document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.id==='modal-close')$('#modal').close();
  if(b.id==='backup-top'||b.hasAttribute('data-backup'))backup();
  if(b.hasAttribute('data-duration')){state.duration=Number(b.dataset.duration);save();render();}
  if(b.hasAttribute('data-filter')){moduleFilter=b.dataset.filter;history.replaceState(null,'','#lessons');render();}
  if(b.hasAttribute('data-start-session')){const n=Number($('#custom-duration')?.value||state.duration);if(!Number.isInteger(n)||n<15||n>240){toast('Chọn số phút nguyên từ 15 đến 240.');return;}if(!state.session){state.duration=n;state.session={id:uid(),lessonId:state.selected,duration:n,elapsed:0,running:true,started:Date.now()};save();}location.hash='session';render();}
  if(b.hasAttribute('data-lesson-tab')){syncDraft();save();lessonTab=b.dataset.lessonTab;render();}
  if(b.hasAttribute('data-hint')){syncDraft();const d=draft(currentLesson().id);d.hints=Math.min(d.hints+1,currentLesson().hints.length);save();render();}
  if(b.hasAttribute('data-transfer')){syncDraft();draft(currentLesson().id).mode='transfer';save();lessonTab='practice';render();}
  if(b.hasAttribute('data-solution')){syncDraft();draft(currentLesson().id).solution=true;save();render();$('#solution').open=true;}
  if(b.hasAttribute('data-copy-code'))copy(b.parentElement.querySelector('code').textContent);
  if(b.hasAttribute('data-seed'))download('SupportLab.sql',C.seed);
  if(b.hasAttribute('data-tutor'))copy(tutorPrompt);
  if(b.hasAttribute('data-download-code')){syncDraft();download(currentLesson().id+'.sql',draft(currentLesson().id).code);}
  if(b.hasAttribute('data-save-attempt')){storeAttempt();toast('Đã lưu mốc thực hành vào Nhật ký.');}
  if(b.hasAttribute('data-new-attempt')){syncDraft();const l=currentLesson(),d=draft(l.id);if(d.code||d.notes||d.output)storeAttempt();state.drafts[l.id]={code:'',output:'',notes:'',question:'',hints:0,solution:false,mode:d.mode,checks:[]};save();render();toast('Lần thử mới. Bài cũ đã giữ trong Nhật ký.');}
  if(b.hasAttribute('data-review')){reviewPacket=packet();save();showModal('Nhờ review khi bạn cần',`<p>Copy nội dung này vào Copilot Chat của SSMS. Copilot đọc editor đang mở; app chỉ cung cấp đề bài, bài làm đã dán và nguyên tắc gợi ý. Đây không phải phản hồi AI tự động.</p><textarea readonly>${escape(reviewPacket)}</textarea><div class="actions"><button class="button" data-copy-packet>Copy ngữ cảnh</button><button class="button secondary" data-download-packet>Tải file Markdown</button></div>`);}
  if(b.hasAttribute('data-copy-packet'))copy(reviewPacket);
  if(b.hasAttribute('data-download-packet'))download('review-context.md',reviewPacket);
  if(b.hasAttribute('data-assess')){syncDraft();const l=currentLesson(),d=draft(l.id),value=b.dataset.assess;if(!d.code.trim()&&!d.notes.trim()){toast('Ghi bài làm hoặc cách suy luận trước khi tự đánh giá.');return;}if(value==='independent'&&(d.hints>0||d.solution)){toast('Lần này có trợ giúp. Hãy ghi nhận đúng; lần ôn sau thử độc lập.');return;}if(value==='independent'&&!l.checks.every((_,i)=>d.checks[i])){toast('Hãy đối chiếu đủ checklist trước khi xác nhận tự làm.');return;}storeAttempt(value);render();toast('Đã ghi nhận. Lịch ôn sẽ dựa trên lần thực hành này.');}
  if(b.hasAttribute('data-pause')){const s=state.session;if(s){s.elapsed=elapsed();s.running=!s.running;s.started=Date.now();save();render();}}
  if(b.hasAttribute('data-finish-session')){const s=state.session;if(!s)return;s.elapsed=elapsed();s.running=false;save();showModal('Khép lại buổi học',`<p>${Math.floor(s.elapsed/60000)} phút tập trung. Bài học vẫn giữ nguyên để tiếp tục lần sau.</p><label for="session-reflection">Một điều đã hiểu và một điều cần ôn</label><textarea id="session-reflection" placeholder="Mình đã hiểu… Buổi sau cần…"></textarea><button class="button" data-confirm-finish>Lưu và kết thúc</button>`);}
  if(b.hasAttribute('data-confirm-finish')){const s=state.session;if(!s)return;state.sessions.push({id:s.id,at:new Date().toISOString(),lessonId:s.lessonId,planned:s.duration,minutes:Math.floor(s.elapsed/60000),reflection:$('#session-reflection').value});state.session=null;save();$('#modal').close();location.hash='notebook';render();toast('Đã lưu buổi học.');}
  if(b.hasAttribute('data-add-note')){const t=$('#quick-note').value.trim();if(!t){toast('Ghi một điều muốn lưu trước nhé.');return;}state.notes.push({id:uid(),at:new Date().toISOString(),text:t});save();render();toast('Đã lưu ghi chú.');}
  if(b.hasAttribute('data-export-md'))exportMd();
  if(b.hasAttribute('data-import'))$('#import-file').click();
  if(b.hasAttribute('data-import-sql')){const f=document.createElement('input');f.type='file';f.accept='.sql,text/plain';f.onchange=async()=>{const file=f.files[0];if(!file)return;if(file.size>1000000){toast('Chọn file SQL nhỏ hơn 1 MB.');return;}const bytes=await file.arrayBuffer();const a=new Uint8Array(bytes);const decoder=new TextDecoder(a[0]===255&&a[1]===254?'utf-16le':a[0]===254&&a[1]===255?'utf-16be':'utf-8');const text=decoder.decode(bytes);syncDraft();draft(currentLesson().id).code=text;save();render();toast('Đã nhập code. File chỉ được đọc, không thực thi.');};f.click();}
 });
 $('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>15000000){toast('File sao lưu phải nhỏ hơn 15 MB.');return;}try{const next=validate(JSON.parse(await f.text()));if(next.session){next.session.elapsed=next.session.elapsed+(next.session.running?Math.max(0,Date.now()-next.session.started):0);next.session.running=false;}showModal('Nhập tiến độ từ thiết bị khác',`<p>File có ${next.attempts.length} lần thử, ${next.sessions.length} buổi học và ${next.notes.length} ghi chú. Nhập sẽ thay thế dữ liệu hiện tại (${state.attempts.length} lần thử). File chỉ chứa dữ liệu, không thực thi code.</p><button class="button secondary" id="backup-before-import">1. Tải bản sao hiện tại</button><button class="button" id="confirm-import" disabled>2. Thay thế bằng file đã chọn</button>`);$('#backup-before-import').onclick=()=>{backup();$('#confirm-import').disabled=false;};$('#confirm-import').onclick=()=>{state=next;save();$('#modal').close();render();toast('Đã nhập tiến độ. Đồng hồ được tạm dừng.');};}catch(err){toast('Không nhập được: '+err.message);}});
 window.addEventListener('hashchange',()=>{syncDraft();save();lessonTab='learn';render();window.scrollTo(0,0);});
 window.addEventListener('pagehide',()=>{syncDraft();if(state.session){state.session.elapsed=elapsed();state.session.started=Date.now();}save();});
 setInterval(()=>{if($('#timer'))$('#timer').textContent=formatTime(elapsed());},1000);
 render();
 // Expose only pure validation/planning helpers to local checks, never credentials.
 window.TechPathDebug={validate,planBlocks,status,lessonCount:C.lessons.length};
})();
